#include <algorithm>
#include <iterator>
#include <numeric>
#include <string>
#include <vector>

struct Player
{
    std::string name{};
    int score{};
};

void sortByScore(std::vector<Player>& players)
{
    std::sort(players.begin(), players.end(), [](const Player& a, const Player& b)
    {
        if (a.score != b.score)
        {
            return a.score > b.score;
        }
        return a.name < b.name;
    });
}

std::vector<Player> scoringAtLeast(const std::vector<Player>& players, int minimum)
{
    std::vector<Player> result{};
    std::copy_if(players.begin(), players.end(), std::back_inserter(result),
        [minimum](const Player& p) { return p.score >= minimum; });
    return result;
}

int totalScore(const std::vector<Player>& players)
{
    return std::accumulate(players.begin(), players.end(), 0,
        [](int sum, const Player& p) { return sum + p.score; });
}

hints:
`std::copy_if` writes to a destination iterator, but an empty vector has no room to write into. `std::back_inserter(result)` (from `<iterator>`) solves that: it is a destination that calls `result.push_back(...)` for every element written to it.

```cpp
std::vector<int> evens{};
std::copy_if(v.begin(), v.end(), std::back_inserter(evens), [](int x) { return x % 2 == 0; });
```

