std::vector<Player> team() { return { { "Cy", 70 }, { "Ann", 50 }, { "Bo", 90 }, { "Di", 70 } }; }
std::string names(const std::vector<Player>& ps) { std::string s; for (const auto& p : ps) { if (!s.empty()) s += ' '; s += p.name; } return s; }

TEST("sortByScore") { auto t{ team() }; sortByScore(t); CHECK_EQ(names(t), "Bo Cy Di Ann"); }
TEST("scoringAtLeast keeps the original order") { CHECK_EQ(names(scoringAtLeast(team(), 70)), "Cy Bo Di"); CHECK_EQ(names(scoringAtLeast(team(), 95)), ""); }
TEST("totalScore") { CHECK_EQ(totalScore(team()), 280); CHECK_EQ(totalScore({}), 0); }

